import { access, rm } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const projectRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));

// Every one of these is regenerated by a normal build. Deleting them first,
// rather than trusting each tool's own incremental/clean-dir logic, is what
// guarantees a serve session can never be looking at a stale artifact from a
// previous build — the exact class of bug that let a fixed defect keep
// reproducing locally after the fix had already landed.
const targets = [
  'public', // Hugo destination dir; --cleanDestinationDir only runs on the next build, not before you serve a leftover one
  'dist', // vite library build output
  'node_modules/.vite', // vite's dependency pre-bundle cache
  '.hugo_build.lock', // leftover lock file from an interrupted hugo run
];

const removed = [];
for (const target of targets) {
  const path = resolve(projectRoot, target);
  const existed = await access(path).then(() => true).catch(() => false);
  if (!existed) continue;
  await rm(path, { recursive: true, force: true });
  removed.push(target);
}

console.log(removed.length ? `Purged: ${removed.join(', ')}` : 'Nothing to purge — already clean.');
